macro_rules! deps {
    () => {
        SizedByDefault!();
        HirDisplayError!();
        HirFormatter!();
    };
}

macro_rules! write_bounds_like_dyn_trait {
    () => {
        deps!();
        fn write_bounds_like_dyn_trait < 'db > (f : & mut HirFormatter < '_ , 'db > , this : Either < Ty < 'db > , Region < 'db > > , predicates : & [Clause < 'db >] , default_sized : SizedByDefault ,) -> Result < () , HirDisplayError > { let mut first = true ; let mut angle_open = false ; let mut is_fn_trait = false ; let mut is_sized = false ; for p in predicates { match p . kind () . skip_binder () { ClauseKind :: Trait (trait_ref) => { let trait_ = trait_ref . def_id () . 0 ; if default_sized . is_sized_trait (trait_ , f . db) { is_sized = true ; if matches ! (default_sized , SizedByDefault :: Sized { .. }) { continue ; } } if ! is_fn_trait { is_fn_trait = fn_traits (f . db , trait_) . any (| it | it == trait_) ; } if ! is_fn_trait && angle_open { write ! (f , ">") ? ; angle_open = false ; } if ! first { write ! (f , " + ") ? ; } f . start_location_link (trait_ . into ()) ; write ! (f , "{}" , f . db . trait_signature (trait_) . name . display (f . db , f . edition ())) ? ; f . end_location_link () ; if is_fn_trait { if let [_self , params @ ..] = trait_ref . trait_ref . args . as_slice () && let Some (args) = params . first () . and_then (| it | it . ty () ? . as_tuple ()) { write ! (f , "(") ? ; hir_fmt_tys (f , args . as_slice () , Some (trait_ref . trait_ref . self_ty ())) ? ; write ! (f , ")") ? ; } } else { let params = generic_args_sans_defaults (f , Some (trait_ . into ()) , trait_ref . trait_ref . args . as_slice () ,) ; if let [_self , params @ ..] = params && ! params . is_empty () { write ! (f , "<") ? ; hir_fmt_generic_arguments (f , params , Some (trait_ref . trait_ref . self_ty ())) ? ; angle_open = true ; } } } ClauseKind :: TypeOutlives (to) if Either :: Left (to . 0) == this => { if ! is_fn_trait && angle_open { write ! (f , ">") ? ; angle_open = false ; } if ! first { write ! (f , " + ") ? ; } to . 1 . hir_fmt (f) ? ; } ClauseKind :: RegionOutlives (lo) if Either :: Right (lo . 0) == this => { if ! is_fn_trait && angle_open { write ! (f , ">") ? ; angle_open = false ; } if ! first { write ! (f , " + ") ? ; } lo . 1 . hir_fmt (f) ? ; } ClauseKind :: Projection (projection) if is_fn_trait => { is_fn_trait = false ; if ! projection . term . as_type () . is_some_and (| it | it . is_unit ()) { write ! (f , " -> ") ? ; projection . term . hir_fmt (f) ? ; } } ClauseKind :: Projection (projection) => { if angle_open { write ! (f , ", ") ? ; } else { write ! (f , "<") ? ; angle_open = true ; } let assoc_ty_id = projection . def_id () . expect_type_alias () ; let type_alias = f . db . type_alias_signature (assoc_ty_id) ; f . start_location_link (assoc_ty_id . into ()) ; write ! (f , "{}" , type_alias . name . display (f . db , f . edition ())) ? ; f . end_location_link () ; let own_args = projection . projection_term . own_args (f . interner) ; if ! own_args . is_empty () { write ! (f , "<") ? ; hir_fmt_generic_arguments (f , own_args . as_slice () , None) ? ; write ! (f , ">") ? ; } write ! (f , " = ") ? ; projection . term . hir_fmt (f) ? ; } _ => { } } first = false ; } if angle_open { write ! (f , ">") ? ; } if let SizedByDefault :: Sized { anchor } = default_sized { let sized_trait = LangItem :: Sized . resolve_trait (f . db , anchor) ; if ! is_sized { if ! first { write ! (f , " + ") ? ; } if let Some (sized_trait) = sized_trait { f . start_location_link (sized_trait . into ()) ; } write ! (f , "?Sized") ? ; } else if first { if let Some (sized_trait) = sized_trait { f . start_location_link (sized_trait . into ()) ; } write ! (f , "Sized") ? ; } if sized_trait . is_some () { f . end_location_link () ; } } Ok (()) }
    };
}

write_bounds_like_dyn_trait!()